        [1412] = L["The lakes of Mulgore are small, clear and patient. The tauren fish them the way they do everything else: slowly, and with thanks."],
        [1413] = L["Every oasis in the Barrens is a meeting place. Whatever drinks there by day, something swims under it by night."],
