        [1439] = L["Darkshore's water is grey, cold and full of wrecks. Half of what bites off Auberdine has made a home in somebody's lost cargo."],
        [1440] = L["The rivers of Ashenvale run under leaves older than most kingdoms. The fish are quick, and the sentinels are quicker to ask what you are doing there."],
        [1441] = L["Down among the Thousand Needles the water is scarce and jealously kept. A fish from here has earned its place."],
        [1442] = L["Stonetalon's lakes sit high and cold between the peaks. The goblins would have drained them by now if the fishing were not so good."],
        [1443] = L["The coast of Desolace is bones and grey surf. Something down there has a taste for both."],
        [1444] = L["Feralas is green all the way down to the waterline. Its rivers are deep, warm and very much alive."],
        [1445] = L["Nobody is sure where Dustwallow's land stops and its water begins. Fish from the shore, and count your toes afterwards."],
        [1446] = L["Steamwheedle Port has the only water worth the name in Tanaris. The goblins will sell you the right to fish it, twice if you let them."],
        [1447] = L["Under Azshara's bright bay lies a drowned city. Old anglers say the big ones live in what used to be its gardens."],
        [1448] = L["The pools of Felwood glow, and not in a good way. What still swims in them is stubborn beyond reason."],
        [1449] = L["The hot springs and tar-rimmed lakes of Un'Goro have kept things the rest of the world forgot. Some of them bite."],
        [1450] = L["Lake Elune'ara in Moonglade is as calm as a held breath. The druids ask only that you take no more than you will eat."],
        [1451] = L["Silithus is sand, wind and the sound of wings. If you have found water to fish here, tell no one."],
        [1452] = L["The lakes of Winterspring freeze at the edges and steam in the middle. The fish there are fat for the cold and worth the walk."],
        [1454] = L["The pools of Orgrimmar are fished by peons with nothing better to do and by old grunts who say the same. Both tell you the big one got away."],
        [1456] = L["A fish from the ponds of Thunder Bluff has lived its whole life a long way above the plains. It seems calm about it."],
        [1457] = L["Darnassus keeps its waters as carefully as its temples. The fish have grown used to being admired."],
