        [1417] = L["Arathi's shores have seen more armies than anglers. The fish have long since stopped caring whose banner flies above the water."],
        [1418] = L["The Badlands are dust from one end to the other. A bite here is a small miracle; treat it as one."],
        [1419] = L["The coast of the Blasted Lands is red, scoured and quiet. Whatever lives in that surf has learned to live with a great deal."],
        [1420] = L["The lakes of Tirisfal lie still under a sickly sky. The Forsaken fish them out of habit; the dead do not eat much, but they remember liking it."],
        [1421] = L["Silverpine's long coast is all mist and pine shadow. The fishing is good, which is the one cheerful thing anyone says about the place."],
        [1422] = L["The rivers of the Western Plaguelands still run, though not clean. What you pull from them, look at twice."],
        [1423] = L["Few people fish the Eastern Plaguelands, and fewer say so. The water keeps what the plague left of it."],
        [1424] = L["Hillsbrad's river and its long southern shore have fed both sides of every quarrel fought over them."],
        [1425] = L["The Hinterlands keep their lakes high among the trees, where the Wildhammer dwarves fish from gryphon-back when they think no one can see."],
