        [1427] = L["The Searing Gorge has lava where other lands have rivers. Bring something to drink instead."],
        [1428] = L["The Burning Steppes are ash and embers. If the water here gives you anything at all, it will be hot."],
        [1429] = L["Every child in Elwynn learns to fish at Crystal Lake or Stone Cairn. The smallfish there have been outwitting them for generations."],
        [1430] = L["Deadwind Pass has little water and less welcome. What is in the pools below Karazhan is best left there."],
        [1431] = L["The river along Duskwood's edge is black at any hour. The fish do not seem to mind the dark; the anglers do."],
        [1432] = L["The Loch is the pride of Loch Modan, held back by the great Stonewrought Dam. Dwarves measure a fishing story against it, and the Loch usually wins."],
